 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh } = THREE;

  const group = new Group();

  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspect = atlasWidth / atlasHeight;

  const width = 2.4;
  const height = width / aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!texture) return;
      texture.colorSpace = THREE.SRGBColorSpace;
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  return group;
}
